 8→#[derive(Parser, Debug)]
 9→#[command(name = "feature-marker-tui")]
10→#[command(author = "Vinicius Carvalho")]
11→#[command(version = "0.1.0")]
12→#[command(about = "Terminal User Interface for Feature-Marker workflow automation")]
13→struct Args {
14→    /// Feature name to work with
15→    #[arg(short, long)]
16→    feature: Option<String>,
17→
18→    /// Project directory (defaults to current directory)
19→    #[arg(short, long)]
20→    project: Option<PathBuf>,
21→
22→    /// Skip to specific execution mode
23→    #[arg(short, long, value_parser = ["full", "tasks-only", "ralph-loop", "spec-driven"])]
24→    mode: Option<String>,
25→
26→    /// Enable debug logging
27→    #[arg(short, long)]
28→    debug: bool,
29→}
30→
31→#[tokio::main]
32→async fn main() -> Result<()> {
33→    let args = Args::parse();
34→
35→    // Initialize logging if debug mode
36→    if args.debug {
37→        tracing_subscriber::fmt()
38→            .with_env_filter("feature_marker_tui=debug")
39→            .init();
40→    }
41→
42→    // Determine project directory
43→    let project_dir = args.project.unwrap_or_else(|| {
44→        std::env::current_dir().expect("Failed to get current directory")
45→    });
46→
47→    // Load configuration
48→    let config = config::load_config(&project_dir)?;
49→
50→    // Create and run the application
51→    let mut app = app::App::new(config, project_dir, args.feature, args.mode)?;
52→    app.run().await
53→}
