16→    tracing_subscriber::registry()
17→        .with(tracing_subscriber::EnvFilter::try_from_default_env()
18→            .unwrap_or_else(|_| "feature_marker_menubar=debug".into()))
19→        .with(tracing_subscriber::fmt::layer())
20→        .init();
