24→    tauri::Builder::default()
25→        .plugin(tauri_plugin_shell::init())
26→        .plugin(tauri_plugin_notification::init())
27→        .plugin(tauri_plugin_dialog::init())
28→        .setup(|app| {
29→            // Initialize shared state
30→            let state = Arc::new(Mutex::new(AppState::new()?));
31→            app.manage(state.clone());
32→
33→            // Set up system tray
34→            tray::setup_tray(app)?;
35→
36→            // Start file watcher for checkpoint changes
37→            let app_handle = app.handle().clone();
38→            let state_clone = state.clone();
39→            tauri::async_runtime::spawn(async move {
40→                if let Err(e) = state::watch_checkpoints(app_handle, state_clone).await {
41→                    tracing::error!("Checkpoint watcher error: {}", e);
42→                }
43→            });
44→
45→            tracing::info!("Feature-Marker Menu Bar initialized successfully");
46→            Ok(())
47→        })
