  9→/// Get list of available features
 10→#[tauri::command]
 11→pub async fn get_features(
 12→    state: State<'_, Arc<Mutex<AppState>>>
 13→) -> Result<Vec<FeatureSummary>, String> {
 14→    let mut state_guard: tokio::sync::MutexGuard<'_, AppState> = state.lock().await;
 15→    state_guard.list_features().map_err(|e: anyhow::Error| e.to_string())
 16→}
