 18→/// Get detailed state of a specific feature
 19→#[tauri::command]
 20→pub async fn get_feature_state(
 21→    state: State<'_, Arc<Mutex<AppState>>>,
 22→    feature: String,
 23→) -> Result<FeatureState, String> {
 24→    let mut state_guard: tokio::sync::MutexGuard<'_, AppState> = state.lock().await;
 25→    state_guard.load_feature_state(&feature).map_err(|e: anyhow::Error| e.to_string())
 26→}
