 33→/// Load the tray icon from the icons directory
 34→fn load_tray_icon() -> Image<'static> {
 35→    // Try to load the tray icon (template icon for macOS menu bar)
 36→    let icon_bytes: &[u8] = include_bytes!("../icons/tray-icon@2x.png");
 37→    Image::from_bytes(icon_bytes)
 38→        .expect("Failed to load tray icon")
 39→        .to_owned()
 40→}
