 90→/// Build the tray context menu
 91→fn build_tray_menu(app: &AppHandle) -> Result<tauri::menu::Menu<tauri::Wry>> {
 92→    // Header
 93→    let header = MenuItemBuilder::with_id("header", "Feature-Marker v2.0.0")
 94→        .enabled(false)
 95→        .build(app)?;
 96→
 97→    // Main actions
 98→    let start_feature = MenuItemBuilder::with_id("start_feature", "Start New Feature...")
 99→        .accelerator("Cmd+N")
100→        .build(app)?;
101→
102→    let resume_feature = MenuItemBuilder::with_id("resume_feature", "Resume Last Feature")
103→        .accelerator("Cmd+R")
104→        .build(app)?;
105→
106→    let show_dashboard = MenuItemBuilder::with_id("show_dashboard", "Show Dashboard")
107→        .accelerator("Cmd+D")
108→        .build(app)?;
109→
110→    // Recent features submenu
111→    let recent_submenu = SubmenuBuilder::new(app, "Recent Features")
112→        .item(&MenuItemBuilder::with_id("no_recent", "No recent features").enabled(false).build(app)?)
113→        .build()?;
114→
115→    // Settings
116→    let set_project = MenuItemBuilder::with_id("set_project", "Set Project Directory...")
117→        .build(app)?;
118→
119→    let preferences = MenuItemBuilder::with_id("preferences", "Preferences...")
120→        .accelerator("Cmd+,")
121→        .build(app)?;
122→
123→    // Quit
124→    let quit = MenuItemBuilder::with_id("quit", "Quit Feature-Marker")
125→        .accelerator("Cmd+Q")
126→        .build(app)?;
127→
128→    let menu = MenuBuilder::new(app)
129→        .item(&header)
130→        .separator()
131→        .item(&start_feature)
132→        .item(&resume_feature)
133→        .separator()
134→        .item(&show_dashboard)
135→        .item(&recent_submenu)
136→        .separator()
137→        .item(&set_project)
138→        .item(&preferences)
139→        .separator()
140→        .item(&quit)
141→        .build()?;
142→
143→    Ok(menu)
144→}
