181→/// Toggle dashboard window visibility
182→fn toggle_dashboard_window(app: &AppHandle) {
183→    if let Some(window) = app.get_webview_window("dashboard") {
184→        if window.is_visible().unwrap_or(false) {
185→            let _ = window.hide();
186→        } else {
187→            position_window_near_tray(app, &window);
188→            let _ = window.show();
189→            let _ = window.set_focus();
190→        }
191→    }
192→}
193→
194→/// Show dashboard with specific mode
195→fn show_dashboard_with_mode(app: &AppHandle, mode: &str) {
196→    let _ = app.emit("set-view-mode", mode);
197→    if let Some(window) = app.get_webview_window("dashboard") {
198→        position_window_near_tray(app, &window);
199→        let _ = window.show();
200→        let _ = window.set_focus();
201→    }
202→}
203→
204→/// Position window near the system tray (below the tray icon)
205→fn position_window_near_tray(_app: &AppHandle, window: &tauri::WebviewWindow) {
206→    let window_size = window.outer_size().unwrap_or(tauri::PhysicalSize::new(400, 500));
207→
208→    // Get the tray icon position, or use a default (right side of screen)
209→    let tray_x = if let Some((x, _)) = get_tray_position() {
210→        x
211→    } else if let Some(monitor) = window.primary_monitor().ok().flatten() {
212→        // Default: position on the right side of the screen (where tray icons usually are)
213→        monitor.size().width as i32 - 200
214→    } else {
215→        800 // Fallback
216→    };
217→
218→    // Position the window centered below the tray icon
219→    // On macOS, the menu bar is at y=0, tray icons are around y=11
220→    // We position the window just below the menu bar (around y=25)
221→    let window_x = tray_x - (window_size.width as i32 / 2);
222→    let window_y = 25; // Just below the macOS menu bar
223→
224→    // Ensure window stays on screen
225→    let final_x = if let Some(monitor) = window.primary_monitor().ok().flatten() {
226→        let monitor_width = monitor.size().width as i32;
227→        // Ensure window doesn't go off right edge
228→        let max_x = monitor_width - window_size.width as i32 - 10;
229→        // Ensure window doesn't go off left edge
230→        window_x.max(10).min(max_x)
231→    } else {
232→        window_x.max(10)
233→    };
234→
235→    let _ = window.set_position(PhysicalPosition::new(final_x, window_y));
236→}
