265→/// Update the tray menu with current features
266→pub async fn update_tray_menu(app: &AppHandle, features: Vec<crate::state::FeatureSummary>) -> Result<()> {
267→    // For now, emit an event to update the menu from the frontend
268→    // Full dynamic menu updates in Tauri v2 require recreating the menu
269→    let _ = app.emit("features-updated", features);
270→    Ok(())
271→}
