 65→    /// Navigate to next screen based on current mode
 66→    pub fn navigate_next(&mut self) {
 67→        self.mode = match &self.mode {
 68→            AppMode::Welcome => AppMode::FeatureSelection,
 69→            AppMode::FeatureSelection => AppMode::ModeSelection,
 70→            AppMode::ModeSelection => AppMode::Executing,
 71→            _ => return,
