  6→/// Manages checkpoint files for feature state persistence
  7→pub struct CheckpointManager {
  8→    state_path: PathBuf,
  9→}
 10→
 11→impl CheckpointManager {
 12→    /// Create a new checkpoint manager
 13→    pub fn new(state_path: PathBuf) -> Self {
 14→        Self { state_path }
 15→    }
 16→
 17→    /// Get the base state directory path
 18→    pub fn state_path(&self) -> &PathBuf {
 19→        &self.state_path
 20→    }
 21→
 22→    /// Get the state directory for a feature
 23→    pub fn feature_dir(&self, feature: &str) -> PathBuf {
 24→        self.state_path.join(feature)
 25→    }
 26→
 27→    /// Get the checkpoint file path for a feature
 28→    pub fn checkpoint_path(&self, feature: &str) -> PathBuf {
 29→        self.feature_dir(feature).join("checkpoint.json")
 30→    }
 31→
 32→    /// Check if a checkpoint exists for a feature
 33→    pub fn exists(&self, feature: &str) -> bool {
 34→        self.checkpoint_path(feature).exists()
 35→    }
 36→
 37→    /// List all features with checkpoints
 38→    pub fn list_features(&self) -> Result<Vec<String>> {
 39→        let mut features = Vec::new();
 40→
 41→        if !self.state_path.exists() {
 42→            return Ok(features);
 43→        }
 44→
 45→        for entry in fs::read_dir(&self.state_path)? {
 46→            let entry = entry?;
 47→            let path = entry.path();
 48→
 49→            if path.is_dir() {
 50→                if let Some(name) = path.file_name().and_then(|n| n.to_str()) {
 51→                    // Check if it has a checkpoint.json
 52→                    if path.join("checkpoint.json").exists() {
 53→                        features.push(name.to_string());
 54→                    }
 55→                }
 56→            }
 57→        }
 58→
 59→        features.sort();
 60→        Ok(features)
 61→    }
 62→
 63→    /// Load checkpoint for a feature
 64→    pub fn load(&self, feature: &str) -> Result<FeatureState> {
 65→        let path = self.checkpoint_path(feature);
 66→        let content = fs::read_to_string(&path)
 67→            .with_context(|| format!("Failed to read checkpoint: {}", path.display()))?;
 68→
 69→        serde_json::from_str(&content)
 70→            .with_context(|| format!("Failed to parse checkpoint: {}", path.display()))
 71→    }
