 24→    if let Some(pos) = TRAY_ICON_POSITION.get() {
 25→        if let Ok(mut p) = pos.lock() {
 26→            *p = (x, y);
 27→        }
 28→    } else {
 29→        let _ = TRAY_ICON_POSITION.set(std::sync::Mutex::new((x, y)));
