121→/// Pause the currently running feature (currently acts as cancel since Claude doesn't support pause)
122→#[tauri::command]
123→pub async fn pause_feature(
124→    app: AppHandle,
125→    state: State<'_, Arc<Mutex<AppState>>>
126→) -> Result<(), String> {
127→    // For now, pause acts the same as cancel since we can't pause the Claude process
128→    // The feature state is maintained in checkpoint files and can be resumed later
129→    let state_guard = state.lock().await;
130→
131→    if let Some(ref running) = state_guard.running_feature {
132→        let _ = app.emit("feature-paused", &running.name);
133→        drop(state_guard);
134→
135→        // Add output
136→        {
137→            let mut state_guard = state.lock().await;
138→            state_guard.add_output("Feature paused. Progress is saved in checkpoint.".to_string());
139→        }
140→        let _ = app.emit("output-line", "Feature paused. Progress is saved in checkpoint.");
141→
142→        // Cancel the running process
143→        cancel_feature(app, state).await
144→    } else {
145→        Err("No feature is currently running".to_string())
146→    }
147→}
