149→/// Cancel the currently running feature
150→#[tauri::command]
151→pub async fn cancel_feature(
152→    app: AppHandle,
153→    state: State<'_, Arc<Mutex<AppState>>>
154→) -> Result<(), String> {
155→    let (running_feature, cancel_sender) = {
156→        let mut state_guard = state.lock().await;
157→
158→        let running = state_guard.running_feature.clone();
159→        let sender = state_guard.cancel_sender.take();
160→
161→        (running, sender)
162→    };
163→
164→    if let Some(running) = running_feature {
165→        // Send cancellation signal
166→        if let Some(sender) = cancel_sender {
167→            let _ = sender.send(());
168→            tracing::info!("Sent cancellation signal for feature: {}", running.name);
169→        } else if let Some(pid) = running.process_id {
170→            // Fallback: kill process directly if no cancel sender
171→            let _ = process_manager::kill_process(pid).await;
172→            tracing::info!("Killed process {} for feature: {}", pid, running.name);
173→        }
174→
175→        // Add to output log
176→        {
177→            let mut state_guard = state.lock().await;
178→            state_guard.add_output("Cancelling feature...".to_string());
179→        }
180→
181→        let _ = app.emit("output-line", "Cancelling feature...");
182→
183→        Ok(())
184→    } else {
185→        Err("No feature is currently running".to_string())
186→    }
187→}
