303→/// App configuration
304→#[derive(Debug, Clone, Serialize, Deserialize)]
305→pub struct AppConfig {
306→    pub project_dir: Option<PathBuf>,
307→    pub feature_marker_path: PathBuf,
308→    pub notifications_enabled: bool,
309→}
