 79→  private setupTauriListeners() {
 80→    const { listen } = window.__TAURI__.event;
 81→
 82→    listen('feature-updated', () => {
 83→      this.loadFeatures().then(() => this.render());
 84→    });
 85→
 86→    listen('feature-started', () => {
 87→      this.loadFeatures().then(() => this.render());
 88→    });
 89→
 90→    listen('feature-completed', () => {
 91→      this.loadFeatures().then(() => this.render());
 92→    });
 93→
 94→    listen('feature-error', () => {
 95→      this.loadFeatures().then(() => this.render());
 96→    });
 97→
 98→    listen('feature-cancelled', () => {
 99→      this.loadFeatures().then(() => this.render());
100→    });
101→
102→    listen('feature-paused', () => {
103→      this.loadFeatures().then(() => this.render());
104→    });
105→
106→    listen('output-line', (event: { payload: unknown }) => {
107→      const line = event.payload as string;
108→      this.outputLog.push(line);
109→      if (this.outputLog.length > 500) {
110→        this.outputLog.shift();
111→      }
112→      this.updateOutputLog();
113→    });
114→
115→    listen('set-view-mode', (event: { payload: unknown }) => {
116→      const mode = event.payload as string;
117→      if (mode === 'start') {
118→        this.showStartView();
119→      } else if (mode === 'settings') {
120→        this.showSettingsView();
121→      } else if (mode === 'list' || mode === 'feature') {
122→        this.showListView();
123→      }
124→    });
125→
126→    listen('select-feature', (event: { payload: unknown }) => {
127→      const feature = event.payload as string;
128→      this.showFeatureDetail(feature);
129→    });
130→
131→    listen('resume-feature', (event: { payload: unknown }) => {
132→      const feature = event.payload as string;
133→      this.resumeFeature(feature);
134→    });
135→  }
