137→  private setupEventListeners() {
138→    document.addEventListener('click', (e) => {
139→      const target = e.target as HTMLElement;
140→
141→      if (target.closest('[data-action="close"]')) {
142→        this.closeWindow();
143→      } else if (target.closest('[data-action="start"]')) {
144→        this.showStartView();
145→      } else if (target.closest('[data-action="back"]')) {
146→        this.showListView();
147→      } else if (target.closest('[data-action="settings"]')) {
148→        this.showSettingsView();
149→      } else if (target.closest('[data-action="refresh"]')) {
150→        this.loadFeatures().then(() => this.render());
151→      } else if (target.closest('[data-action="start-feature"]')) {
152→        this.startFeature();
153→      } else if (target.closest('[data-action="pause"]')) {
154→        this.pauseFeature();
155→      } else if (target.closest('[data-action="cancel"]')) {
156→        this.cancelFeature();
157→      } else if (target.closest('[data-action="open-dir"]')) {
158→        this.openProjectDir();
159→      } else if (target.closest('[data-action="set-project"]')) {
160→        this.setProjectDir();
161→      } else if (target.closest('.feature-item')) {
162→        const featureName = target.closest('.feature-item')?.getAttribute('data-feature');
163→        if (featureName) {
164→          this.showFeatureDetail(featureName);
165→        }
166→      }
167→    });
168→  }
