file.content:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --bg-primary: #1e1e2e;
  --bg-secondary: #2a2a3e;
  --bg-tertiary: #313244;
  --text-primary: #cdd6f4;
  --text-secondary: #a6adc8;
  --text-muted: #6c7086;
  --accent: #89b4fa;
  --accent-hover: #b4befe;
  --success: #a6e3a1;
  --warning: #f9e2af;
  --error: #f38ba8;
  --border: #45475a;
  --shadow: rgba(0, 0, 0, 0.3);
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
  font-size: 13px;
  line-height: 1.4;
  background: var(--bg-primary);
  color: var(--text-primary);
  overflow: hidden;
  user-select: none;
  -webkit-user-select: none;
}

#app {
  height: 100vh;
  display: flex;
  flex-direction: column;
}

/* Header */
.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  -webkit-app-region: drag;
}

.header h1 {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
}

.header-actions {
  display: flex;
  gap: 8px;
  -webkit-app-region: no-drag;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 6px 12px;
  border: none;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s ease;
}

.btn-primary {
  background: var(--accent);
  color: var(--bg-primary);
}

.btn-primary:hover {
  background: var(--accent-hover);
}

.btn-secondary {
  background: var(--bg-tertiary);
  color: var(--text-primary);
  border: 1px solid var(--border);
}

.btn-secondary:hover {
  background: var(--border);
}

.btn-icon {
  width: 28px;
  height: 28px;
  padding: 0;
  background: transparent;
  border: none;
  color: var(--text-secondary);
  cursor: pointer;
  border-radius: 4px;
}

.btn-icon:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

/* Main content area */
.content {
  flex: 1;
  overflow-y: auto;
  padding: 12px;
}

/* Feature list */
.feature-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.feature-item {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  background: var(--bg-secondary);
  border-radius: 8px;
  border: 1px solid var(--border);
  cursor: pointer;
  transition: all 0.15s ease;
}

.feature-item:hover {
  border-color: var(--accent);
}

.feature-item.running {
  border-color: var(--success);
  background: rgba(166, 227, 161, 0.05);
}

.feature-item.error {
  border-color: var(--error);
  background: rgba(243, 139, 168, 0.05);
}

.feature-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.feature-name {
  font-weight: 600;
  color: var(--text-primary);
  font-size: 13px;
}

.feature-status {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 10px;
  background: var(--bg-tertiary);
  color: var(--text-secondary);
}

.feature-status.running {
  background: var(--success);
  color: var(--bg-primary);
}

.feature-status.error {
  background: var(--error);
  color: var(--bg-primary);
}

.feature-status.paused {
  background: var(--warning);
  color: var(--bg-primary);
}

/* Progress bar */
.progress-container {
  display: flex;
  align-items: center;
  gap: 8px;
}

.progress-bar {
  flex: 1;
  height: 4px;
  background: var(--bg-tertiary);
  border-radius: 2px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: var(--accent);
  border-radius: 2px;
  transition: width 0.3s ease;
}

.progress-fill.running {
  background: var(--success);
}

.progress-text {
  font-size: 11px;
  color: var(--text-muted);
  min-width: 70px;
  text-align: right;
}

/* Phase indicator */
.phase-indicator {
  display: flex;
  gap: 4px;
  margin-top: 4px;
}

.phase-dot {
  width: 8px;
  height: 8px;
