.feature-detail-header {
  margin-bottom: 16px;
}

.feature-detail-header h2 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 4px;
}

.feature-detail-header .meta {
  font-size: 11px;
  color: var(--text-muted);
}

.phase-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.phase-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  background: var(--bg-secondary);
  border-radius: 6px;
  border: 1px solid var(--border);
}

.phase-number {
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-tertiary);
  border-radius: 50%;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
}

.phase-item.completed .phase-number {
  background: var(--success);
  color: var(--bg-primary);
}

.phase-item.current .phase-number {
  background: var(--accent);
  color: var(--bg-primary);
}

.phase-item.error .phase-number {
  background: var(--error);
  color: var(--bg-primary);
}

.phase-info {
  flex: 1;
}

.phase-name {
  font-size: 13px;
  font-weight: 500;
}

.phase-status-text {
  font-size: 11px;
  color: var(--text-muted);
}

/* Action buttons row */
.action-buttons {
  display: flex;
  gap: 8px;
  margin-top: 16px;
}

.action-buttons .btn {
  flex: 1;
}

/* Settings view */
.settings-group {
  margin-bottom: 20px;
}

.settings-group h3 {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 12px;
}

.settings-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 0;
  border-bottom: 1px solid var(--border);
}

.settings-item:last-child {
  border-bottom: none;
}

.settings-label {
  font-size: 13px;
  color: var(--text-primary);
}

.settings-value {
  font-size: 12px;
  color: var(--text-muted);
  max-width: 200px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

