 12→/// Shared application state
 13→pub struct AppState {
 14→    /// Current project directory
 15→    pub project_dir: Option<PathBuf>,
 16→    /// Path to feature-marker-dist
 17→    pub feature_marker_path: PathBuf,
 18→    /// Currently running feature (if any)
 19→    pub running_feature: Option<RunningFeature>,
 20→    /// Cached feature states
 21→    pub features: HashMap<String, FeatureState>,
 22→    /// Output log buffer
 23→    pub output_log: Vec<String>,
 24→    /// Cancel sender for stopping the running process
 25→    pub cancel_sender: Option<oneshot::Sender<()>>,
 26→}
 27→
 28→impl AppState {
 29→    pub fn new() -> Result<Self> {
 30→        // Find feature-marker-dist path
 31→        let feature_marker_path = find_feature_marker_path()?;
 32→
 33→        Ok(Self {
 34→            project_dir: std::env::current_dir().ok(),
 35→            feature_marker_path,
 36→            running_feature: None,
 37→            features: HashMap::new(),
 38→            output_log: Vec::new(),
 39→            cancel_sender: None,
 40→        })
 41→    }
 42→
 43→    /// Get state directory path
 44→    pub fn state_dir(&self) -> Option<PathBuf> {
 45→        self.project_dir.as_ref().map(|p| p.join(".claude/feature-state"))
 46→    }
 47→
 48→    /// List available features
 49→    pub fn list_features(&mut self) -> Result<Vec<FeatureSummary>> {
 50→        let state_dir = match self.state_dir() {
 51→            Some(dir) if dir.exists() => dir,
 52→            _ => return Ok(Vec::new()),
 53→        };
 54→
 55→        let mut features = Vec::new();
 56→        for entry in std::fs::read_dir(&state_dir)? {
 57→            let entry = entry?;
 58→            let path = entry.path();
 59→
 60→            if path.is_dir() {
 61→                let checkpoint_path = path.join("checkpoint.json");
 62→                if checkpoint_path.exists() {
 63→                    if let Some(name) = path.file_name().and_then(|n| n.to_str()) {
 64→                        if let Ok(state) = self.load_feature_state(name) {
 65→                            features.push(FeatureSummary {
 66→                                name: name.to_string(),
 67→                                current_phase: state.current_phase,
 68→                                total_phases: 5,
 69→                                phase_status: format!("{:?}", state.phase_status),
 70→                                last_updated: state.last_updated,
 71→                                is_running: self.running_feature.as_ref()
 72→                                    .map(|r| r.name == name)
 73→                                    .unwrap_or(false),
 74→                                paused: state.paused,
 75→                                has_error: state.error_state.is_some(),
 76→                            });
 77→                        }
 78→                    }
 79→                }
 80→            }
 81→        }
 82→
 83→        features.sort_by(|a, b| b.last_updated.cmp(&a.last_updated));
 84→        Ok(features)
 85→    }
 86→
 87→    /// Load feature state from checkpoint
 88→    pub fn load_feature_state(&mut self, feature: &str) -> Result<FeatureState> {
 89→        let state_dir = self.state_dir()
 90→            .context("No project directory set")?;
 91→
 92→        let checkpoint_path = state_dir.join(feature).join("checkpoint.json");
 93→        let content = std::fs::read_to_string(&checkpoint_path)
 94→            .with_context(|| format!("Failed to read checkpoint: {}", checkpoint_path.display()))?;
 95→
 96→        let state: FeatureState = serde_json::from_str(&content)
 97→            .with_context(|| format!("Failed to parse checkpoint: {}", checkpoint_path.display()))?;
 98→
 99→        self.features.insert(feature.to_string(), state.clone());
100→        Ok(state)
101→    }
102→
103→    /// Add output line to log
104→    pub fn add_output(&mut self, line: String) {
105→        // Keep last 1000 lines
106→        if self.output_log.len() > 1000 {
107→            self.output_log.remove(0);
108→        }
109→        self.output_log.push(line);
110→    }
111→
112→    /// Clear output log
113→    pub fn clear_output(&mut self) {
114→        self.output_log.clear();
115→    }
116→}
