118→/// Find feature-marker-dist installation path
119→fn find_feature_marker_path() -> Result<PathBuf> {
120→    // Check common locations
121→    let candidates = [
122→        // User's home directory
123→        dirs::home_dir().map(|h| h.join(".feature-marker")),
124→        // XDG data directory
125→        dirs::data_dir().map(|d| d.join("feature-marker")),
126→        // Relative to this binary
127→        std::env::current_exe().ok().and_then(|e| e.parent().map(|p| p.to_path_buf())),
128→    ];
129→
130→    for candidate in candidates.into_iter().flatten() {
131→        if candidate.join("feature-marker.sh").exists() {
132→            return Ok(candidate);
133→        }
134→    }
135→
136→    // Default to home directory installation
137→    Ok(dirs::home_dir()
138→        .context("Could not find home directory")?
139→        .join(".feature-marker"))
140→}
