210→/// Watch for checkpoint file changes
211→pub async fn watch_checkpoints(
212→    app_handle: AppHandle,
213→    state: Arc<Mutex<AppState>>,
214→) -> Result<()> {
215→    let (tx, rx) = std::sync::mpsc::channel();
216→
217→    let mut watcher = RecommendedWatcher::new(
218→        move |res| {
219→            let _ = tx.send(res);
220→        },
221→        Config::default().with_poll_interval(Duration::from_millis(500)),
222→    )?;
223→
224→    // Initial setup - watch state directory if it exists
225→    {
226→        let state_guard = state.lock().await;
227→        if let Some(state_dir) = state_guard.state_dir() {
228→            if state_dir.exists() {
229→                watcher.watch(&state_dir, RecursiveMode::Recursive)?;
230→            }
231→        }
232→    }
233→
234→    loop {
235→        match rx.recv_timeout(Duration::from_millis(100)) {
236→            Ok(Ok(event)) => {
237→                for path in &event.paths {
238→                    if path.file_name().map(|n| n == "checkpoint.json").unwrap_or(false) {
239→                        match event.kind {
240→                            notify::EventKind::Modify(_) | notify::EventKind::Create(_) => {
241→                                if let Some(feature_dir) = path.parent() {
242→                                    if let Some(feature_name) = feature_dir.file_name() {
243→                                        let feature = feature_name.to_string_lossy().to_string();
244→                                        tracing::debug!("Checkpoint updated: {}", feature);
245→
246→                                        // Reload state and emit event
247→                                        let mut state_guard = state.lock().await;
248→                                        if let Ok(feature_state) = state_guard.load_feature_state(&feature) {
249→                                            let _ = app_handle.emit("feature-updated", &feature_state);
250→
251→                                            // Check for phase completion
252→                                            check_phase_completion(&app_handle, &feature_state);
253→                                        }
254→                                    }
255→                                }
256→                            }
257→                            _ => {}
258→                        }
259→                    }
260→                }
261→            }
262→            Ok(Err(e)) => {
263→                tracing::warn!("Watcher error: {}", e);
264→            }
265→            Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {
266→                // Check if we need to update watched directory
267→                tokio::time::sleep(Duration::from_secs(1)).await;
268→            }
269→            Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => {
270→                tracing::error!("Watcher channel disconnected");
271→                break;
272→            }
273→        }
274→    }
275→
276→    Ok(())
277→}
278→
279→/// Check for phase completion and send notification
280→fn check_phase_completion(app_handle: &AppHandle, state: &FeatureState) {
281→    let phase_names = ["Inputs Gate", "Analysis & Planning", "Implementation", "Tests & Validation", "Commit & PR"];
282→
283→    for (i, name) in phase_names.iter().enumerate() {
284→        if let Some(phase) = state.phases.get(&i.to_string()) {
285→            if phase.status == PhaseStatus::Completed {
286→                if let Some(completed_at) = phase.completed_at {
287→                    // Check if this was completed recently (within 5 seconds)
288→                    let now = Utc::now();
289→                    let diff = now.signed_duration_since(completed_at);
290→                    if diff.num_seconds() < 5 && diff.num_seconds() >= 0 {
291→                        let _ = app_handle.emit("phase-completed", serde_json::json!({
292→                            "feature": state.feature_name,
293→                            "phase": i,
294→                            "phase_name": name,
295→                        }));
296→                    }
297→                }
298→            }
299→        }
300→    }
301→}
