 28→/// Start a new feature workflow - spawns claude as child process
 29→#[tauri::command]
 30→pub async fn start_feature(
 31→    app: AppHandle,
 32→    state: State<'_, Arc<Mutex<AppState>>>,
 33→    feature: String,
 34→    mode: Option<String>,
 35→) -> Result<(), String> {
 36→    let mode = mode.unwrap_or_else(|| "full".to_string());
 37→
 38→    // Check if there's already a running feature
 39→    {
 40→        let state_guard = state.lock().await;
 41→        if state_guard.running_feature.is_some() {
 42→            return Err("A feature is already running. Please wait or cancel it first.".to_string());
 43→        }
 44→    }
 45→
 46→    // Get project directory
 47→    let project_dir = {
 48→        let state_guard: tokio::sync::MutexGuard<'_, AppState> = state.lock().await;
 49→        state_guard.project_dir.clone()
 50→    };
 51→
 52→    let project_dir = project_dir.ok_or("No project directory set. Please set a project directory first via Settings.")?;
 53→
 54→    if !project_dir.exists() {
 55→        return Err(format!("Project directory does not exist: {}", project_dir.display()));
 56→    }
 57→
 58→    // Set running feature
 59→    {
 60→        let mut state_guard: tokio::sync::MutexGuard<'_, AppState> = state.lock().await;
 61→        state_guard.running_feature = Some(RunningFeature {
 62→            name: feature.clone(),
 63→            mode: mode.clone(),
 64→            started_at: Utc::now(),
 65→            process_id: None, // Will be set by process_manager
 66→        });
 67→        state_guard.clear_output();
 68→    }
 69→
 70→    // Add initial output
 71→    {
 72→        let mut state_guard = state.lock().await;
 73→        state_guard.add_output(format!("Starting feature: {}", feature));
 74→        state_guard.add_output(format!("Mode: {}", mode));
 75→        state_guard.add_output(format!("Project: {}", project_dir.display()));
 76→        state_guard.add_output("".to_string());
 77→    }
 78→
 79→    // Emit initial output lines to UI
 80→    let _ = app.emit("output-line", format!("Starting feature: {}", feature));
 81→    let _ = app.emit("output-line", format!("Mode: {}", mode));
 82→    let _ = app.emit("output-line", format!("Project: {}", project_dir.display()));
 83→    let _ = app.emit("output-line", "");
 84→
 85→    tracing::info!("Starting feature {} in mode {} for project {}", feature, mode, project_dir.display());
 86→
 87→    // Spawn the claude process
 88→    let state_arc = state.inner().clone();
 89→    match process_manager::spawn_claude_process(
 90→        app.clone(),
 91→        state_arc,
 92→        project_dir,
 93→        feature.clone(),
 94→        mode,
 95→    ).await {
 96→        Ok(pid) => {
 97→            tracing::info!("Claude process spawned with PID: {}", pid);
 98→            let _ = app.emit("feature-started", &feature);
 99→            let _ = app.emit("output-line", format!("Process started (PID: {})", pid));
100→            Ok(())
101→        }
102→        Err(e) => {
103→            // Clear running feature on error
104→            let mut state_guard = state.lock().await;
105→            state_guard.running_feature = None;
106→            Err(format!("Failed to start feature: {}", e))
107→        }
108→    }
109→}
