 11→/// Result of starting a process
 12→#[allow(dead_code)]
 13→pub struct ProcessHandle {
 14→    pub child: Child,
 15→    pub cancel_tx: oneshot::Sender<()>,
 16→}
 17→
 18→/// Spawn the claude command as a child process with output streaming
 19→pub async fn spawn_claude_process(
 20→    app_handle: AppHandle,
 21→    state: Arc<Mutex<AppState>>,
 22→    project_dir: PathBuf,
 23→    feature: String,
 24→    mode: String,
 25→) -> Result<u32, String> {
 26→    // Create cancellation channel
 27→    let (cancel_tx, cancel_rx) = oneshot::channel::<()>();
 28→
 29→    // Build the command
 30→    // We need to source the cargo env first to ensure claude is in PATH
 31→    let shell_command = format!(
 32→        "source $HOME/.cargo/env 2>/dev/null; cd '{}' && claude --dangerously-skip-permissions '/feature-marker --mode {} {}'",
 33→        project_dir.display(),
 34→        mode,
 35→        feature
 36→    );
 37→
 38→    tracing::info!("Spawning claude process: {}", shell_command);
 39→
 40→    let mut child = Command::new("sh")
 41→        .arg("-c")
 42→        .arg(&shell_command)
 43→        .stdout(Stdio::piped())
 44→        .stderr(Stdio::piped())
 45→        .kill_on_drop(true)
 46→        .spawn()
 47→        .map_err(|e| format!("Failed to spawn process: {}", e))?;
 48→
 49→    let pid = child.id().ok_or("Failed to get process ID")?;
 50→
 51→    // Store PID in state
 52→    {
 53→        let mut state_guard = state.lock().await;
 54→        if let Some(ref mut running) = state_guard.running_feature {
 55→            running.process_id = Some(pid);
 56→        }
 57→    }
 58→
 59→    // Store cancel sender in state
 60→    {
 61→        let mut state_guard = state.lock().await;
 62→        state_guard.cancel_sender = Some(cancel_tx);
 63→    }
 64→
 65→    // Take stdout and stderr
 66→    let stdout = child.stdout.take();
 67→    let stderr = child.stderr.take();
 68→
 69→    // Spawn background task to read stdout
 70→    let app_handle_stdout = app_handle.clone();
 71→    let state_stdout = state.clone();
 72→    let feature_stdout = feature.clone();
 73→
 74→    if let Some(stdout) = stdout {
 75→        tokio::spawn(async move {
 76→            let reader = BufReader::new(stdout);
 77→            let mut lines = reader.lines();
 78→
 79→            while let Ok(Some(line)) = lines.next_line().await {
 80→                // Emit to UI
 81→                let _ = app_handle_stdout.emit("output-line", &line);
 82→
 83→                // Store in state
 84→                let mut state_guard = state_stdout.lock().await;
 85→                state_guard.add_output(line);
 86→            }
 87→
 88→            tracing::debug!("stdout reader finished for feature: {}", feature_stdout);
 89→        });
 90→    }
 91→
 92→    // Spawn background task to read stderr
 93→    let app_handle_stderr = app_handle.clone();
 94→    let state_stderr = state.clone();
 95→    let feature_stderr = feature.clone();
 96→
 97→    if let Some(stderr) = stderr {
 98→        tokio::spawn(async move {
 99→            let reader = BufReader::new(stderr);
100→            let mut lines = reader.lines();
101→
102→            while let Ok(Some(line)) = lines.next_line().await {
103→                let stderr_line = format!("[stderr] {}", line);
104→
105→                // Emit to UI
106→                let _ = app_handle_stderr.emit("output-line", &stderr_line);
107→
108→                // Store in state
109→                let mut state_guard = state_stderr.lock().await;
110→                state_guard.add_output(stderr_line);
111→            }
112→
113→            tracing::debug!("stderr reader finished for feature: {}", feature_stderr);
114→        });
115→    }
116→
117→    // Spawn background task to wait for process completion or cancellation
118→    let app_handle_wait = app_handle.clone();
119→    let state_wait = state.clone();
120→    let feature_wait = feature.clone();
121→
122→    tokio::spawn(async move {
123→        tokio::select! {
124→            // Process completed naturally
125→            result = child.wait() => {
126→                match result {
127→                    Ok(status) => {
128→                        let msg = if status.success() {
129→                            format!("Feature '{}' completed successfully", feature_wait)
130→                        } else {
131→                            format!("Feature '{}' exited with status: {}", feature_wait, status)
132→                        };
133→
134→                        tracing::info!("{}", msg);
135→
136→                        // Emit completion event
137→                        let _ = app_handle_wait.emit("output-line", &msg);
138→
139→                        if status.success() {
140→                            let _ = app_handle_wait.emit("feature-completed", &feature_wait);
141→                        } else {
142→                            let _ = app_handle_wait.emit("feature-error", serde_json::json!({
143→                                "feature": feature_wait,
144→                                "error": format!("Process exited with status: {}", status)
145→                            }));
146→                        }
147→                    }
148→                    Err(e) => {
149→                        tracing::error!("Error waiting for process: {}", e);
150→                        let _ = app_handle_wait.emit("feature-error", serde_json::json!({
151→                            "feature": feature_wait,
152→                            "error": e.to_string()
153→                        }));
154→                    }
155→                }
156→
157→                // Clear running feature
158→                let mut state_guard = state_wait.lock().await;
159→                state_guard.running_feature = None;
160→                state_guard.cancel_sender = None;
161→            }
162→
163→            // Cancellation requested
164→            _ = cancel_rx => {
165→                tracing::info!("Cancellation requested for feature: {}", feature_wait);
166→
167→                // Kill the process
168→                let _ = child.kill().await;
169→
170→                let msg = format!("Feature '{}' was cancelled", feature_wait);
171→                let _ = app_handle_wait.emit("output-line", &msg);
172→                let _ = app_handle_wait.emit("feature-cancelled", &feature_wait);
173→
174→                // Clear running feature
175→                let mut state_guard = state_wait.lock().await;
176→                state_guard.running_feature = None;
177→                state_guard.cancel_sender = None;
178→            }
179→        }
180→    });
181→
182→    Ok(pid)
183→}
184→
185→/// Kill a process by PID
186→pub async fn kill_process(pid: u32) -> Result<(), String> {
187→    #[cfg(unix)]
188→    {
189→        // Send SIGTERM first for graceful shutdown
190→        let result = std::process::Command::new("kill")
191→            .arg("-TERM")
192→            .arg(pid.to_string())
193→            .status();
194→
195→        match result {
196→            Ok(status) if status.success() => {
197→                tracing::info!("Sent SIGTERM to process {}", pid);
198→                Ok(())
199→            }
200→            _ => {
201→                // If SIGTERM fails, try SIGKILL
202→                let result = std::process::Command::new("kill")
203→                    .arg("-9")
204→                    .arg(pid.to_string())
205→                    .status();
206→
207→                match result {
208→                    Ok(status) if status.success() => {
209→                        tracing::info!("Sent SIGKILL to process {}", pid);
210→                        Ok(())
211→                    }
212→                    _ => Err(format!("Failed to kill process {}", pid)),
213→                }
214→            }
215→        }
216→    }
217→
218→    #[cfg(not(unix))]
219→    {
220→        Err("Process killing is only supported on Unix systems".to_string())
221→    }
222→}
