 12→// Store the tray icon position for window positioning
 13→static TRAY_ICON_POSITION: std::sync::OnceLock<std::sync::Mutex<(i32, i32)>> = std::sync::OnceLock::new();
 14→
 15→fn get_tray_position() -> Option<(i32, i32)> {
 16→    TRAY_ICON_POSITION
 17→        .get()
 18→        .and_then(|pos| pos.lock().ok())
 19→        .map(|p| *p)
 20→        .filter(|(x, _)| *x > 0) // Only return if we have a valid position
 21→}
 22→
 23→fn set_tray_position(x: i32, y: i32) {
 24→    if let Some(pos) = TRAY_ICON_POSITION.get() {
 25→        if let Ok(mut p) = pos.lock() {
 26→            *p = (x, y);
 27→        }
 28→    } else {
 29→        let _ = TRAY_ICON_POSITION.set(std::sync::Mutex::new((x, y)));
 30→    }
 31→}
