 42→/// Set up the system tray with menu
 43→pub fn setup_tray(app: &tauri::App) -> Result<()> {
 44→    let app_handle = app.handle();
 45→
 46→    // Build the tray menu
 47→    let menu = build_tray_menu(app_handle)?;
 48→
 49→    // Load the tray icon (template icon for macOS menu bar)
 50→    let tray_icon = load_tray_icon();
 51→
 52→    // Create tray icon
 53→    let _tray = TrayIconBuilder::with_id("main")
 54→        .icon(tray_icon)
 55→        .icon_as_template(true) // Makes the icon adapt to light/dark mode on macOS
 56→        .menu(&menu)
 57→        .tooltip("Feature-Marker")
 58→        .on_menu_event(move |app, event| {
 59→            handle_menu_event(app, event.id().as_ref());
 60→        })
 61→        .on_tray_icon_event(|tray, event| {
 62→            match event {
 63→                TrayIconEvent::Click {
 64→                    button: MouseButton::Left,
 65→                    button_state: MouseButtonState::Up,
 66→                    position,
 67→                    ..
 68→                } => {
 69→                    // Store the tray icon position for window positioning
 70→                    set_tray_position(position.x as i32, position.y as i32);
 71→                    let app = tray.app_handle();
 72→                    toggle_dashboard_window(app);
 73→                }
 74→                // Capture position from any click for later use
 75→                TrayIconEvent::Click { position, .. } => {
 76→                    set_tray_position(position.x as i32, position.y as i32);
 77→                }
 78→                // Capture position when mouse enters tray icon area
 79→                TrayIconEvent::Enter { position, .. } => {
 80→                    set_tray_position(position.x as i32, position.y as i32);
 81→                }
 82→                _ => {}
 83→            }
 84→        })
 85→        .build(app)?;
 86→
 87→    Ok(())
 88→}
