106→    let show_dashboard = MenuItemBuilder::with_id("show_dashboard", "Show Dashboard")
107→        .accelerator("Cmd+D")
108→        .build(app)?;
109→
110→    // Recent features submenu
111→    let recent_submenu = SubmenuBuilder::new(app, "Recent Features")
112→        .item(&MenuItemBuilder::with_id("no_recent", "No recent features").enabled(false).build(app)?)
113→        .build()?;
114→
115→    // Settings
116→    let set_project = MenuItemBuilder::with_id("set_project", "Set Project Directory...")
117→        .build(app)?;
