146→/// Handle tray menu events
147→fn handle_menu_event(app: &AppHandle, event_id: &str) {
148→    match event_id {
149→        "start_feature" => {
150→            show_dashboard_with_mode(app, "start");
151→        }
152→        "resume_feature" => {
153→            let app_handle = app.clone();
154→            tauri::async_runtime::spawn(async move {
155→                resume_last_feature(&app_handle).await;
156→            });
157→        }
158→        "show_dashboard" => {
159→            toggle_dashboard_window(app);
160→        }
161→        "set_project" => {
162→            let _ = app.emit("show-project-picker", ());
163→        }
164→        "preferences" => {
165→            show_dashboard_with_mode(app, "settings");
166→        }
167→        "quit" => {
168→            app.exit(0);
169→        }
170→        id if id.starts_with("feature_") => {
171→            let feature_name = id.strip_prefix("feature_").unwrap_or("");
172→            let _ = app.emit("select-feature", feature_name);
173→            show_dashboard_with_mode(app, "feature");
174→        }
175→        _ => {
176→            tracing::debug!("Unhandled menu event: {}", event_id);
177→        }
178→    }
179→}
