238→/// Resume the last active feature
239→async fn resume_last_feature(app: &AppHandle) {
240→    let state = app.state::<Arc<Mutex<AppState>>>();
241→    let mut state_guard = state.lock().await;
242→
243→    match state_guard.list_features() {
244→        Ok(features) => {
245→            if let Some(last_feature) = features.first() {
246→                let feature_name = last_feature.name.clone();
247→                drop(state_guard);
248→                let _ = app.emit("resume-feature", &feature_name);
249→                show_dashboard_with_mode(app, "feature");
250→            } else {
251→                drop(state_guard);
252→                // No features found, show the list view (which displays empty state)
253→                show_dashboard_with_mode(app, "list");
254→            }
255→        }
256→        Err(e) => {
257→            tracing::error!("Failed to list features: {}", e);
258→            drop(state_guard);
259→            // Show list view on error
260→            show_dashboard_with_mode(app, "list");
261→        }
262→    }
263→}
