273→  private updateOutputLog() {
274→    const logEl = document.getElementById('output-log');
275→    if (logEl) {
276→      const lastLines = this.outputLog.slice(-100);
277→      logEl.innerHTML = lastLines.map(line => {
278→        const cls = line.includes('[stderr]') ? 'error' : line.includes('\u2713') || line.includes('\u2705') ? 'success' : '';
279→        return `<div class="line ${cls}">${this.escapeHtml(line)}</div>`;
280→      }).join('');
281→      logEl.scrollTop = logEl.scrollHeight;
282→    }
