## 5. Models (Codable)

### FeatureState.swift

Matching the checkpoint.json structure exactly. The existing JSON uses string keys for the phases map ("0", "1", etc.) and snake_case for all field names.

```swift
import Foundation

struct FeatureState: Codable, Sendable {
    let version: String
    let featureName: String
    let projectPath: String
    let currentPhase: Int
    let phaseStatus: PhaseStatus
    let phases: [String: Phase]
    let lastUpdated: Date
    var paused: Bool = false
    var errorState: String?

    enum CodingKeys: String, CodingKey {
        case version
        case featureName = "feature_name"
        case projectPath = "project_path"
        case currentPhase = "current_phase"
        case phaseStatus = "phase_status"
        case phases
        case lastUpdated = "last_updated"
        case paused
        case errorState = "error_state"
    }
}

enum PhaseStatus: String, Codable, Sendable {
    case pending
    case inProgress = "in_progress"
    case completed
    case error
}

struct Phase: Codable, Sendable {
    let name: String
    let status: PhaseStatus
    var startedAt: Date?
    var completedAt: Date?
    var currentTaskIndex: Int?
    var totalTasks: Int?
    var completedTasks: [Int] = []
    var outputs: [String] = []

    enum CodingKeys: String, CodingKey {
        case name, status
        case startedAt = "started_at"
        case completedAt = "completed_at"
        case currentTaskIndex = "current_task_index"
        case totalTasks = "total_tasks"
        case completedTasks = "completed_tasks"
        case outputs
    }
}

struct FeatureSummary: Identifiable, Sendable {
    var id: String { name }
    let name: String
    let currentPhase: Int
    let totalPhases: Int   // always 5
    let phaseStatus: PhaseStatus
    let lastUpdated: Date
    let isRunning: Bool
    let paused: Bool
    let hasError: Bool
}

struct RunningFeature: Sendable {
    let name: String
    let mode: String
    let startedAt: Date
    var processID: Int32?
}

struct AppConfiguration: Sendable {
    var projectDir: URL?
    var featureMarkerPath: URL
    let version: String = "2.0.0"
}
```

The JSONDecoder will use:
```swift
let decoder = JSONDecoder()
decoder.keyDecodingStrategy = .convertFromSnakeCase  // not needed since we use CodingKeys
decoder.dateDecodingStrategy = .custom { decoder in
    // Parse ISO 8601 with fractional seconds
    let container = try decoder.singleValueContainer()
    let dateString = try container.decode(String.self)
    // Try ISO8601 with fractional seconds, then without
    ...
}
```

Note: The existing checkpoint files use ISO 8601 with microseconds (`2026-02-20T17:57:43.956018Z`), so `.iso8601` strategy alone will not work. A custom date formatter handling fractional seconds is required.

