## 7. MenuBar/StatusBarController.swift

This is the critical AppKit integration layer. SwiftUI's `MenuBarExtra` cannot provide an NSPopover. We use NSStatusItem directly.

```swift
import AppKit
import SwiftUI

@MainActor
final class StatusBarController {
    static var shared: StatusBarController?

    private var statusItem: NSStatusItem
    private var popover: NSPopover
    private var menu: NSMenu
    private var eventMonitor: Any?
    private let appState: AppState

    init(appState: AppState) {
        self.appState = appState
        Self.shared = self

        // Create status item
        statusItem = NSStatusBar.system.statusItem(withLength: NSStatusItem.squareLength)

        // Set template icon
        if let button = statusItem.button {
            let icon = NSImage(named: "tray-icon")  // from asset catalog or bundle
            icon?.isTemplate = true  // adapts to light/dark
            button.image = icon
            button.action = #selector(togglePopover(_:))
            button.target = self  // requires NSObject subclass or selector bridging
            button.sendAction(on: [.leftMouseUp, .rightMouseUp])
        }

        // Create popover with SwiftUI content
        popover = NSPopover()
        popover.contentSize = NSSize(width: 400, height: 500)
        popover.behavior = .transient  // closes when clicking outside
        popover.animates = true
        popover.contentViewController = NSHostingController(
            rootView: DashboardView(appState: appState)
        )

        // Build context menu
        menu = buildMenu()

        // Monitor clicks outside to close popover
        eventMonitor = NSEvent.addGlobalMonitorForEvents(
            matching: [.leftMouseDown, .rightMouseDown]
        ) { [weak self] _ in
            self?.closePopover()
        }
    }

    @objc func togglePopover(_ sender: NSStatusBarButton) {
        let event = NSApp.currentEvent!

        if event.type == .rightMouseUp {
            // Show context menu
            statusItem.menu = menu
            statusItem.button?.performClick(nil)
            statusItem.menu = nil  // Reset so left-click works
        } else {
            // Toggle popover
            if popover.isShown {
                closePopover()
            } else {
                showPopover()
            }
        }
    }

    func showPopover() {
        guard let button = statusItem.button else { return }
        popover.show(relativeTo: button.bounds, of: button, preferredEdge: .minY)
        NSApp.activate(ignoringOtherApps: true)
    }

    func closePopover() {
        popover.performClose(nil)
    }

    private func buildMenu() -> NSMenu {
        let menu = NSMenu()

        // Header
        let header = NSMenuItem(title: "Feature-Marker v2.0.0", action: nil, keyEquivalent: "")
        header.isEnabled = false
        menu.addItem(header)
        menu.addItem(.separator())

        let startItem = NSMenuItem(title: "Start New Feature...", action: #selector(menuStartFeature), keyEquivalent: "n")
        startItem.keyEquivalentModifierMask = .command
        menu.addItem(startItem)

        let resumeItem = NSMenuItem(title: "Resume Last Feature", action: #selector(menuResumeFeature), keyEquivalent: "r")
        resumeItem.keyEquivalentModifierMask = .command
        menu.addItem(resumeItem)

        menu.addItem(.separator())

        let dashboardItem = NSMenuItem(title: "Show Dashboard", action: #selector(menuShowDashboard), keyEquivalent: "d")
        dashboardItem.keyEquivalentModifierMask = .command
        menu.addItem(dashboardItem)

        // Recent Features submenu
        let recentSubmenu = NSMenu(title: "Recent Features")
        let recentItem = NSMenuItem(title: "Recent Features", action: nil, keyEquivalent: "")
        recentItem.submenu = recentSubmenu
        menu.addItem(recentItem)

        menu.addItem(.separator())

        menu.addItem(NSMenuItem(title: "Set Project Directory...", action: #selector(menuSetProject), keyEquivalent: ""))

        let prefsItem = NSMenuItem(title: "Preferences...", action: #selector(menuShowPreferences), keyEquivalent: ",")
        prefsItem.keyEquivalentModifierMask = .command
        menu.addItem(prefsItem)

        menu.addItem(.separator())

        let quitItem = NSMenuItem(title: "Quit Feature-Marker", action: #selector(menuQuit), keyEquivalent: "q")
        quitItem.keyEquivalentModifierMask = .command
        menu.addItem(quitItem)

        return menu
    }
}
```

The `StatusBarController` needs to be an NSObject subclass for `@objc` selectors. An alternative is to use closures via `NSMenuItem`'s block-based API on macOS 14+, but since we target macOS 15+, either approach works.

## 8. Process Management (Actor)

### ProcessManager.swift

```swift
import Foundation

actor ProcessManager {
    private var currentProcess: Process?
    private var outputPipe: Pipe?
    private var errorPipe: Pipe?

    var isRunning: Bool {
        currentProcess?.isRunning ?? false
    }

    var processID: Int32? {
        currentProcess?.processIdentifier
    }

    func spawn(
        projectDir: URL,
        feature: String,
        mode: String,
        onOutput: @MainActor @Sendable (String, Bool) -> Void,
        onComplete: @MainActor @Sendable (Bool) -> Void
    ) throws -> Int32 {
        guard currentProcess == nil else {
            throw ProcessError.alreadyRunning
        }

        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/bin/sh")
        process.arguments = [
            "-c",
            "source $HOME/.cargo/env 2>/dev/null; cd '\(projectDir.path)' && claude --dangerously-skip-permissions '/feature-marker --mode \(mode) \(feature)'"
        ]

        let stdoutPipe = Pipe()
        let stderrPipe = Pipe()
        process.standardOutput = stdoutPipe
        process.standardError = stderrPipe

        // Read stdout asynchronously
        stdoutPipe.fileHandleForReading.readabilityHandler = { handle in
            let data = handle.availableData
            guard !data.isEmpty, let line = String(data: data, encoding: .utf8) else { return }
            Task { @MainActor in
                for l in line.components(separatedBy: .newlines) where !l.isEmpty {
                    onOutput(l, false)
                }
            }
        }

        // Read stderr asynchronously
        stderrPipe.fileHandleForReading.readabilityHandler = { handle in
            let data = handle.availableData
            guard !data.isEmpty, let line = String(data: data, encoding: .utf8) else { return }
            Task { @MainActor in
                for l in line.components(separatedBy: .newlines) where !l.isEmpty {
                    onOutput("[stderr] \(l)", true)
                }
            }
        }

        // Termination handler
        process.terminationHandler = { proc in
            stdoutPipe.fileHandleForReading.readabilityHandler = nil
            stderrPipe.fileHandleForReading.readabilityHandler = nil
            Task { @MainActor in
                onComplete(proc.terminationStatus == 0)
            }
        }

        try process.run()
        self.currentProcess = process
        self.outputPipe = stdoutPipe
        self.errorPipe = stderrPipe

        return process.processIdentifier
    }

    func cancel() {
        guard let process = currentProcess, process.isRunning else { return }

        // SIGTERM first
        process.terminate()  // sends SIGTERM

        // If still running after 3 seconds, SIGKILL
        Task {
            try? await Task.sleep(for: .seconds(3))
            if process.isRunning {
                kill(process.processIdentifier, SIGKILL)
            }
        }
    }

    func forceKill() {
        guard let process = currentProcess else { return }
        if process.isRunning {
            kill(process.processIdentifier, SIGKILL)
        }
        currentProcess = nil
    }

    enum ProcessError: Error {
        case alreadyRunning
    }
}
```

Key difference from the Rust version: Foundation's `Process` (formerly NSTask) is the native macOS API for child processes. It supports `terminationHandler` for async completion notification and Pipe for stdout/stderr streaming. No need for tokio -- Foundation's run loop handles I/O.

The `readabilityHandler` closure fires on a background queue whenever data is available. We dispatch to `@MainActor` for state updates.

## 9. File Watching (Actor)

### FileWatcher.swift

```swift
import Foundation

actor FileWatcher {
    private var source: DispatchSourceFileSystemObject?
    private var directoryHandle: CInt = -1
    private var lastKnownStates: [String: Date] = [:]

    func watch(
        directory: URL,
        onChange: @MainActor @Sendable (String) -> Void
    ) {
        stop()

        let path = directory.path
        directoryHandle = open(path, O_EVTONLY)
        guard directoryHandle != -1 else { return }

        source = DispatchSource.makeFileSystemObjectSource(
            fileDescriptor: directoryHandle,
            eventMask: [.write, .extend, .attrib],
            queue: DispatchQueue.global(qos: .utility)
        )

        source?.setEventHandler { [weak self] in
            Task { await self?.scanForChanges(in: directory, onChange: onChange) }
        }

        source?.setCancelHandler { [fd = directoryHandle] in
            close(fd)
        }

        source?.resume()

        // Also set up a periodic poll as backup (every 2 seconds)
        // GCD dispatch source only fires on directory-level changes
        Task {
            while !Task.isCancelled {
                try? await Task.sleep(for: .seconds(2))
                await scanForChanges(in: directory, onChange: onChange)
            }
        }
    }

    private func scanForChanges(
        in directory: URL,
        onChange: @MainActor @Sendable (String) -> Void
    ) {
        let fm = FileManager.default
        guard let entries = try? fm.contentsOfDirectory(
            at: directory,
            includingPropertiesForKeys: [.contentModificationDateKey],
            options: [.skipsHiddenFiles]
        ) else { return }

        for entry in entries where entry.hasDirectoryPath {
            let checkpoint = entry.appendingPathComponent("checkpoint.json")
            guard fm.fileExists(atPath: checkpoint.path) else { continue }

            let attrs = try? fm.attributesOfItem(atPath: checkpoint.path)
            let modDate = attrs?[.modificationDate] as? Date ?? .distantPast
            let featureName = entry.lastPathComponent

            if let lastDate = lastKnownStates[featureName], modDate > lastDate {
                Task { @MainActor in
                    onChange(featureName)
                }
            }
            lastKnownStates[featureName] = modDate
        }
    }

    func stop() {
        source?.cancel()
        source = nil
    }
}
```

An alternative approach is using `FSEventStreamCreate` directly for recursive file system events, which is what the `notify` crate uses under the hood on macOS. However, for this use case (watching a single directory with ~5-20 subdirectories), the DispatchSource + periodic scan approach is simpler and completely sufficient. It avoids the complexity of the FSEvents C API while achieving the same result.

## 10. PathResolver.swift

```swift
import Foundation

enum PathResolver {
    static func findFeatureMarkerPath() -> URL {
        let candidates: [URL?] = [
            FileManager.default.homeDirectoryForCurrentUser
                .appendingPathComponent(".feature-marker"),
            FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first?
                .appendingPathComponent("feature-marker"),
            Bundle.main.executableURL?.deletingLastPathComponent()
        ]

        for case let candidate? in candidates {
            let script = candidate.appendingPathComponent("feature-marker.sh")
            if FileManager.default.fileExists(atPath: script.path) {
                return candidate
            }
        }

        // Default fallback
        return FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent(".feature-marker")
    }
}
```

## 11. NotificationService.swift

```swift
import UserNotifications

enum NotificationService {
    static func requestPermission() async {
        let center = UNUserNotificationCenter.current()
        try? await center.requestAuthorization(options: [.alert, .sound])
    }

    static func sendPhaseCompletion(feature: String, phaseName: String, phaseIndex: Int) {
        let content = UNMutableNotificationContent()
        content.title = "Phase Completed"
        content.body = "\(feature): \(phaseName) completed"
        content.sound = .default

        let request = UNNotificationRequest(
            identifier: "phase-\(feature)-\(phaseIndex)",
            content: content,
            trigger: nil  // deliver immediately
        )

        UNUserNotificationCenter.current().add(request)
    }
}
```

## 12. Helper Utilities

### Opening Finder and Terminal

```swift
// Open in Finder
NSWorkspace.shared.open(projectDirURL)

// Open Terminal at directory
let script = """
tell application "Terminal"
    activate
    do script "cd '\(projectDir.path)'"
end tell
"""
if let appleScript = NSAppleScript(source: script) {
    var error: NSDictionary?
    appleScript.executeAndReturnError(&error)
}
```

### NSOpenPanel for directory selection

```swift
let panel = NSOpenPanel()
panel.canChooseFiles = false
panel.canChooseDirectories = true
panel.allowsMultipleSelection = false
panel.title = "Select Project Directory"

if panel.runModal() == .OK, let url = panel.url {
    appState.projectDir = url
    appState.loadFeatures()
}
```

This is better than SwiftUI's `.fileImporter` because NSOpenPanel gives precise control and is well-tested for directory selection from a popover context.

## 13. Size Optimization Strategies

### Build Configuration

1. **Strip symbols**: `-Xswiftc -whole-module-optimization` is default in release. Add `-Xlinker -dead_strip` to remove unused code.
2. **No Info.plist bloat**: SPM generates a minimal one. For the .app bundle, include only what is needed.
3. **No XIBs/Storyboards**: Everything is code. No Interface Builder resources.
4. **No asset catalog overhead**: Embed the template icon directly as PNG data in the binary (like the Rust version does with `include_bytes!`), or use a minimal asset catalog with just the 2 icon files.
5. **Release build flags** in Package.swift or build command:
   ```
   swift build -c release -Xswiftc -Osize
   ```
   `-Osize` optimizes for binary size rather than speed. For a menu bar app, the difference in runtime performance is negligible.

6. **No unnecessary frameworks**: By using only Foundation, AppKit, SwiftUI, UserNotifications, and Observation, we avoid pulling in heavyweight frameworks. SwiftUI is already loaded by the system (shared dylib), so it adds zero to on-disk binary size.

### Expected Binary Size Estimate

| Component | Size |
|-----------|------|
| Swift runtime | 0 (system-provided on macOS 15) |
| SwiftUI framework | 0 (system dylib) |
| AppKit framework | 0 (system dylib) |
| Application code (~20 files, ~2500 lines) | ~500 KB |
| Icon resources (2 PNGs) | ~1 KB |
| Metadata (Info.plist, etc.) | ~2 KB |
| **Total estimated binary** | **~500 KB - 1 MB** |

Compared to the current Tauri binary: **13 MB** (which includes Rust runtime, Tauri framework, WKWebView bridge, bundled HTML/CSS/JS, tokio async runtime, notify, chrono, serde, and all transitive dependencies).

**Estimated size reduction: ~92-96%** (from 13 MB to ~0.5-1 MB).

The .app bundle will be slightly larger (includes the binary, Info.plist, icons, and framework references), but should stay under 2 MB total.

## 14. Implementation Phases

### Phase 1: Foundation (Files 1-5)
1. `Package.swift` -- project manifest
2. `FeatureMarkerApp.swift` -- @main entry point
3. `AppDelegate.swift` -- NSApplicationDelegate
4. `FeatureState.swift` -- all Codable models
5. `AppConfiguration.swift` -- config model

### Phase 2: Core Services (Files 6-9)
6. `PathResolver.swift` -- find installation
7. `AppState.swift` -- @Observable state
8. `FileWatcher.swift` -- directory monitoring actor
9. `ProcessManager.swift` -- CLI spawning actor

### Phase 3: Menu Bar Integration (File 10)
10. `StatusBarController.swift` -- NSStatusItem + NSPopover + NSMenu

### Phase 4: Views (Files 11-19)
11. `DashboardView.swift` -- root container
12. `ListView.swift` -- feature list
13. `StartView.swift` -- new feature form
14. `DetailView.swift` -- feature detail
15. `SettingsView.swift` -- preferences
16. `FeatureRowView.swift` -- list item component
17. `PhaseDotsView.swift` -- dots component
18. `PhasePillView.swift` -- status badge
19. `OutputLogView.swift` -- log viewer
20. `ProgressBarView.swift` -- progress bar

### Phase 5: Polish (File 20+)
21. `NotificationService.swift` -- phase completion notifications
22. Copy tray icon PNGs to Resources/
23. Build script (build.sh) for release + signing
24. Testing

## 15. Key Architectural Decisions and Rationale

**Decision 1: NSStatusItem + NSPopover over MenuBarExtra**
- `MenuBarExtra` with `.window` style creates a detached window, not a popover anchored to the tray icon. The popover appearance (anchored below the icon with an arrow, `.transient` dismissal) matches what macOS users expect from menu bar apps like Bartender, iStatMenus, etc.

**Decision 2: Foundation Process over custom exec/fork**
- `Process` (NSTask) handles child process lifecycle, pipes, environment, and working directory. It wraps `posix_spawn` internally. No need for lower-level APIs.

**Decision 3: DispatchSource over FSEvents or polling-only**
- DispatchSource.makeFileSystemObjectSource is the recommended way to watch a directory for changes in a lightweight manner. We supplement with a 2-second poll to catch nested file changes that the directory-level source might miss. This avoids the complexity of raw FSEvents while being more responsive than pure polling.

**Decision 4: Single @Observable class over multiple stores**
- The app has a small, well-defined state surface. Splitting into multiple observable objects would add indirection without benefit. SwiftUI + @Observable provides property-level tracking, so only views reading a specific property re-render when it changes.

**Decision 5: No Combine, no async sequences for output streaming**
- The `readabilityHandler` callback pattern on Pipe.FileHandleForReading is the simplest approach. It fires on data availability and we dispatch to @MainActor. No need for AsyncStream, Combine publishers, or reactive patterns for this use case.

**Decision 6: No external dependencies**
- The Tauri version required: tokio, serde, notify, chrono, dirs, anyhow, thiserror, tracing. Every one of these has a Foundation equivalent:
  - tokio -> structured concurrency (Task, async/await)
  - serde -> Codable
  - notify -> DispatchSource + FileManager
  - chrono -> Foundation Date + ISO8601DateFormatter
  - dirs -> FileManager.default.homeDirectoryForCurrentUser / .urls(for:in:)
  - anyhow/thiserror -> Swift Error protocol
  - tracing -> os_log / Logger

## 16. Potential Challenges

1. **NSPopover from SPM executable**: SPM executables are not .app bundles by default. To get proper macOS app behavior (activation policy, popover positioning, Info.plist), the build process needs to create a .app bundle. This can be done with a post-build script that wraps the binary in the standard `.app/Contents/MacOS/` structure with an Info.plist.

2. **Right-click context menu on NSStatusItem**: The standard pattern is to set `statusItem.menu` before the click and clear it after. This requires careful handling in the `sendAction(on:)` callback to distinguish left from right clicks.

3. **ISO 8601 date parsing with microseconds**: The checkpoint files use `2026-02-20T17:57:43.956018Z` which has 6 fractional digits. Foundation's `ISO8601DateFormatter` supports `.withFractionalSeconds` but only up to millisecond precision. A custom DateFormatter or manual parsing may be needed for microsecond timestamps.

4. **Process cleanup on app termination**: The `applicationWillTerminate` delegate method has limited time to execute. The force kill path should be synchronous (using `kill(pid, SIGKILL)` directly) rather than async to ensure it completes before the app exits.

---

